"""Column helpers every table shares. See `app/items/models.py` for how they are used."""

from datetime import UTC, datetime

from sqlalchemy import BigInteger, Integer

# HANA wants BIGINT ... GENERATED BY DEFAULT AS IDENTITY; SQLite only autoincrements a
# column declared exactly INTEGER PRIMARY KEY, so it gets a variant.
ID_TYPE = BigInteger().with_variant(Integer, "sqlite")


def utcnow() -> datetime:
    # Naive UTC, matching what the database's own CURRENT_UTCTIMESTAMP would store
    return datetime.now(UTC).replace(tzinfo=None)
